"use client";

import { cn } from "../lib/cn";
import type { AccordionLook } from "../lib/looks";
import { MOTION_DEFAULTS, type AccordionMotion } from "../lib/motion";
import {
  useId,
  useState,
  type HTMLAttributes,
  type ReactNode,
} from "react";

export type { AccordionLook, AccordionMotion };

export type AccordionItem = {
  value: string;
  trigger: ReactNode;
  content: ReactNode;
  disabled?: boolean;
};

export type AccordionType = "single" | "multiple";

export type AccordionProps = Omit<HTMLAttributes<HTMLDivElement>, "onChange"> & {
  items: AccordionItem[];
  /** single = one panel; multiple = many open */
  type?: AccordionType;
  /**
   * Controlled value:
   * - single → string ("" when none)
   * - multiple → string[]
   */
  value?: string | string[];
  defaultValue?: string | string[];
  onValueChange?: (value: string | string[]) => void;
  /**
   * When `type="single"`, allow closing the open item (value → "").
   * Default true.
   */
  collapsible?: boolean;
  /** soft | solid | glass | outline */
  look?: AccordionLook;
  /** none | fade | height */
  motion?: AccordionMotion;
};

function ChevronIcon({ open }: { open: boolean }) {
  return (
    <span
      className="sg-accordion-chevron-wrap"
      data-open={open || undefined}
      aria-hidden="true"
    >
      <svg className="sg-accordion-chevron" viewBox="0 0 20 20" fill="none">
        <path
          d="M5.5 7.75 10 12.25l4.5-4.5"
          stroke="currentColor"
          strokeWidth="1.8"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    </span>
  );
}

function normalizeDefault(
  type: AccordionType,
  defaultValue?: string | string[],
): string | string[] {
  if (type === "multiple") {
    if (Array.isArray(defaultValue)) return defaultValue;
    if (typeof defaultValue === "string" && defaultValue) return [defaultValue];
    return [];
  }
  if (typeof defaultValue === "string") return defaultValue;
  if (Array.isArray(defaultValue)) return defaultValue[0] ?? "";
  return "";
}

function isOpen(
  type: AccordionType,
  current: string | string[],
  itemValue: string,
): boolean {
  if (type === "multiple") {
    return Array.isArray(current) && current.includes(itemValue);
  }
  return current === itemValue;
}

/**
 * Molecule — Accordion
 * Items API first (Select / Dropdown language). Single or multiple open panels.
 */
export function Accordion({
  className,
  items,
  type = "single",
  value: valueProp,
  defaultValue,
  onValueChange,
  collapsible = true,
  look = "soft",
  motion = MOTION_DEFAULTS.accordion,
  ...props
}: AccordionProps) {
  const baseId = useId();
  const isControlled = valueProp !== undefined;
  const [uncontrolled, setUncontrolled] = useState(() =>
    normalizeDefault(type, defaultValue),
  );
  const current = isControlled ? valueProp : uncontrolled;

  function commit(next: string | string[]) {
    if (!isControlled) setUncontrolled(next);
    onValueChange?.(next);
  }

  function toggle(itemValue: string, disabled?: boolean) {
    if (disabled) return;

    if (type === "multiple") {
      const list = Array.isArray(current) ? current : [];
      const next = list.includes(itemValue)
        ? list.filter((v) => v !== itemValue)
        : [...list, itemValue];
      commit(next);
      return;
    }

    const open = current === itemValue;
    if (open) {
      if (collapsible) commit("");
      return;
    }
    commit(itemValue);
  }

  return (
    <div
      className={cn("sg-accordion", className)}
      data-look={look}
      data-motion={motion}
      data-type={type}
      {...props}
    >
      {items.map((item) => {
        const open = isOpen(type, current, item.value);
        const triggerId = `${baseId}-trigger-${item.value}`;
        const panelId = `${baseId}-panel-${item.value}`;

        return (
          <div
            key={item.value}
            className="sg-accordion-item"
            data-state={open ? "open" : "closed"}
            data-disabled={item.disabled || undefined}
          >
            <h3 className="sg-accordion-heading">
              <button
                type="button"
                id={triggerId}
                className="sg-accordion-trigger"
                aria-expanded={open}
                aria-controls={panelId}
                disabled={item.disabled}
                data-state={open ? "open" : "closed"}
                onClick={() => toggle(item.value, item.disabled)}
              >
                <span className="sg-accordion-trigger-label">{item.trigger}</span>
                <ChevronIcon open={open} />
              </button>
            </h3>
            {/* Closed panels stay out of layout — no continuous grid animation */}
            <div
              id={panelId}
              role="region"
              aria-labelledby={triggerId}
              className="sg-accordion-panel"
              data-state={open ? "open" : "closed"}
              hidden={!open}
            >
              <div className="sg-accordion-content">{item.content}</div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

/** Values allowed in `cn(...)` — only strings survive. */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type ClassValue = string | false | null | undefined | 0 | 0n | boolean;

/**
 * Tiny class merger — no runtime deps.
 * Prefer this over pulling tailwind-merge until we need conflict resolution.
 */
export function cn(...parts: ClassValue[]): string {
  return parts.filter((part): part is string => typeof part === "string" && part.length > 0).join(" ");
}

/** Shared visual “look” languages across controls. */

export type ButtonLook = "solid" | "soft" | "glass" | "gradient" | "neon";

export type RadioLook = "dot" | "card" | "chip";

export type CheckboxLook = "box" | "card" | "pill";

export type SwitchLook = "track" | "ios" | "minimal";

export type BadgeLook = "soft" | "solid" | "outline" | "glow";

export type FieldLook = "solid" | "underline" | "filled" | "ghost";

export type SelectLook = "solid" | "soft" | "glass" | "gradient";

export type TabsLook = "pill" | "underline" | "segmented";

export type AvatarLook = "circle" | "rounded" | "soft";

export type TooltipLook = "frost" | "solid" | "accent";

export type CardLook = "flat" | "raised" | "outline" | "glow";

/** NumberInput shell + stepper language */
export type NumberInputLook = "soft" | "solid" | "outline" | "ghost";

/** Slider track / thumb language */
export type SliderLook = "soft" | "solid" | "glass" | "accent";

/** FileField trigger surface */
export type FileFieldLook = "solid" | "soft" | "dashed" | "ghost";

/** Progress track / fill language */
export type ProgressLook = "soft" | "solid" | "glass" | "accent" | "striped";

/** StatusDot chrome language (color still from status / color) */
export type StatusDotLook = "soft" | "solid" | "outline" | "glow";

/** Chip surface language */
export type ChipLook = "soft" | "solid" | "outline" | "glass" | "glow";

/** CloseButton chrome */
export type CloseButtonLook = "ghost" | "soft" | "solid" | "danger";

/**
 * Collapsible / Accordion disclosure surface
 * soft = frost card · solid = long content · glass = chrome · outline = border only · ghost = flush list
 */
export type CollapsibleLook = "soft" | "solid" | "glass" | "outline" | "ghost";

export type AccordionLook = CollapsibleLook;

/** Breadcrumb chrome: plain path · soft tray · pill chips */
export type BreadcrumbLook = "plain" | "soft" | "pill";

/** Pagination control chrome */
export type PaginationLook = "soft" | "solid" | "ghost" | "glass";

/** EmptyState surface */
export type EmptyStateLook = "solid" | "soft" | "outline";

/**
 * Stepper language
 * soft = frost track · solid = solid rail · outline = line only
 * dots = progress line + large dots · pills = segmented chip row
 */
export type StepperLook = "soft" | "solid" | "outline" | "dots" | "pills";

/**
 * Toolbar strip
 * soft | solid | glass | ghost | accent (accent edge rail)
 */
export type ToolbarLook = "soft" | "solid" | "glass" | "ghost" | "accent";

/** List host surface */
export type ListLook = "soft" | "solid" | "outline" | "ghost" | "inset";

/**
 * Stat metric tile
 * solid | soft | glass | outline | accent (left rail)
 */
export type StatLook = "solid" | "soft" | "glass" | "outline" | "accent";

/** PageHeader chrome: plain flush · soft frost · solid panel · glass chrome */
export type PageHeaderLook = "plain" | "soft" | "solid" | "glass";

/** SettingsSection panel chrome */
export type SettingsSectionLook = "soft" | "solid" | "glass" | "plain";

/**
 * Motion recipes — component-specific animation menus.
 * Parallel to `look` (visual surface). Always pair with `prefers-reduced-motion`.
 *
 * Defaults match the pre-motion global micro-interactions so existing UIs
 * keep the same feel when no prop is passed.
 */

/** Shared “off” token used on every control. */
export type MotionNone = "none";

export type ButtonMotion = MotionNone | "lift" | "press" | "sheen" | "ripple";

export type CheckboxMotion = MotionNone | "pop" | "draw" | "fade-in" | "bounce";

export type RadioMotion = MotionNone | "pop" | "dot-scale" | "ring-expand";

export type SwitchMotion = MotionNone | "snap" | "spring" | "elastic";

export type FieldMotion = MotionNone | "ring" | "underline-grow" | "glow";

export type SelectMotion = MotionNone | "fade" | "scale" | "slide-down";

export type TooltipMotion = MotionNone | "fade" | "scale" | "slide";

export type BadgeMotion = MotionNone | "pulse" | "pop-in" | "shimmer";

export type AvatarMotion = MotionNone | "lift" | "ring-pulse" | "status-ping";

/**
 * Tabs indicator + content enter.
 * - none: instant active swap
 * - fade: soft cross-fade on active chrome / content
 * - slide: moving pill or underline indicator (content still fades)
 */
export type TabsMotion = MotionNone | "fade" | "slide";

export type ModalMotion = MotionNone | "scale" | "fade" | "slide-up";

export type ToastMotion = MotionNone | "slide-in" | "pop";

export type CardMotion = MotionNone | "lift" | "glow-pulse";

/** Popover / DropdownMenu panel enter (same recipe set as Select menu). */
export type PopoverMotion = MotionNone | "fade" | "scale" | "slide-down";

export type DropdownMenuMotion = MotionNone | "fade" | "scale" | "slide-down";

/** ContextMenu panel — same recipes as DropdownMenu / Popover. */
export type ContextMenuMotion = MotionNone | "fade" | "scale" | "slide-down";

/** DatePicker calendar panel — same recipes as Select. */
export type DatePickerMotion = MotionNone | "fade" | "scale" | "slide-down";

/** Collapsible / Accordion panel open motion. */
export type CollapsibleMotion = MotionNone | "fade" | "height";

export type AccordionMotion = CollapsibleMotion;

/** Sheet edge panel enter/exit. */
export type SheetMotion = MotionNone | "slide" | "fade";

/** HoverCard panel (Popover family). */
export type HoverCardMotion = MotionNone | "fade" | "scale" | "slide-down";

/** Defaults — preserve current product feel. */
export const MOTION_DEFAULTS = {
  button: "lift",
  checkbox: "pop",
  radio: "pop",
  switch: "spring",
  field: "ring",
  select: "scale",
  tooltip: "scale",
  badge: "none",
  avatar: "lift",
  tabs: "slide",
  modal: "scale",
  toast: "slide-in",
  card: "lift",
  popover: "scale",
  dropdownMenu: "scale",
  contextMenu: "scale",
  datePicker: "scale",
  collapsible: "height",
  accordion: "height",
  sheet: "slide",
  hoverCard: "scale",
} as const satisfies Record<string, string>;
